BEGIN;
UPDATE sub_classes SET description = 'You stand at the front of every fight, holding the line so your allies don''t have to. Enemies who try to slip past you find themselves locked in place.' WHERE id = 1;
UPDATE sub_classes SET description = 'You have mastered every weapon you have ever picked up, and you carry one you trust like a part of yourself. Your technique turns a simple swing into an art.' WHERE id = 2;
UPDATE sub_classes SET description = 'You lead from the front, calling the shots and pointing your allies at the gaps. One shout from you can rally a broken line and turn a losing fight around.' WHERE id = 3;
UPDATE sub_classes SET description = 'You study raw elemental magic and shape it into fire, lightning, and frost. Your spells hit harder than most, and you can bend the blast around your friends.' WHERE id = 4;
UPDATE sub_classes SET description = 'You have studied the art of magic but still prefer a more physical combat approach. You weave runes into your armor and weapons to give you an edge over non-magic combatants.' WHERE id = 5;
UPDATE sub_classes SET description = 'You treat magic as a library to be mastered, collecting every secret you can find. You read omens, steal spells from your rivals, and forget nothing.' WHERE id = 6;
UPDATE sub_classes SET description = 'You curse your enemies and make those curses linger. Your hexes spread from one victim to the next, until the very ground beneath them turns against them.' WHERE id = 7;
UPDATE sub_classes SET description = 'You pay for power with your own blood, and you are always willing to pay. Your hexes drain life from your foes to heal the wounds your magic carves into you.' WHERE id = 8;
UPDATE sub_classes SET description = 'You see the threads of fate and know which ones to pull. You twist luck in your favor, curse your enemies with doom, and slip out of fates meant for you.' WHERE id = 9;
UPDATE sub_classes SET description = 'You draw your magic from the wild green, letting things bloom or rot at your word. Vines snare your foes and the forest canopy hides you from sight.' WHERE id = 10;
UPDATE sub_classes SET description = 'You have studied witchcraft but still prefer the weight of armor and a blade in hand. You curse your foes with every strike and wear black plate laced with hexes.' WHERE id = 11;
UPDATE sub_classes SET description = 'You swore your oath to living things, the root and the leaf and the green that endures. Vines bind your foes and your strikes carry the strength of growing life.' WHERE id = 12;
UPDATE sub_classes SET description = 'You swore your oath to the dead and to the memory of those who passed on. You guide lost souls home and strike down those who cheat their way out of the grave.' WHERE id = 13;
UPDATE sub_classes SET description = 'You swore your oath in the dark, bringing judgment where light cannot reach. You slip through shadows and strike before your enemies know they are hunted.' WHERE id = 14;
UPDATE sub_classes SET description = 'You swore your oath to the distant stars and the cold void between them. You mark your foes with starlight and cut them down with blades edged in the dark beyond.' WHERE id = 15;
UPDATE sub_classes SET description = 'You strike from the dark and are gone before the body hits the floor. Shadows bend to carry you, and in time they learn to fight beside you.' WHERE id = 16;
UPDATE sub_classes SET description = 'You trust poison more than steel, mixing toxins that sap strength and cloud the mind. Your own blood has turned bitter from years of handling them.' WHERE id = 17;
UPDATE sub_classes SET description = 'You can become anyone, slipping into a stolen face and leaving no trace behind. When the job is done, even the people who saw you forget you were there.' WHERE id = 18;
UPDATE sub_classes SET description = 'You were raised in the saddle, and you and your mount fight as one. Your charges break lines and knock riders to the dirt.' WHERE id = 19;
UPDATE sub_classes SET description = 'You plant your shield and become the wall your allies hide behind. Charges break against you, and no one gets past while you stand.' WHERE id = 20;
UPDATE sub_classes SET description = 'You have sworn your life to protect someone greater than yourself. You challenge any who threaten your charge and will step in front of the blade meant for them.' WHERE id = 21;
UPDATE sub_classes SET description = 'You live and die by the bow, whether up close or from across the field. Your aim is patient and your arrows fall like rain on anyone who stands against you.' WHERE id = 22;
UPDATE sub_classes SET description = 'You never hunt alone, with a loyal beast always at your side. The two of you move as one, sharing every target and guarding each other''s backs.' WHERE id = 23;
UPDATE sub_classes SET description = 'You blend steel and spellwork, fighting with a blade in each hand. You dart in and out of the fight, marking your prey with hexes your blades follow home.' WHERE id = 24;
UPDATE sub_classes SET description = 'You draw strength from deep roots, wrapping yourself in bark and holding enemies fast with the grasping earth. Trees open paths for you, and forests rise where you call them.' WHERE id = 25;
UPDATE sub_classes SET description = 'You would rather fight with fang and claw than with spells. You take the shapes of beasts and elements alike, becoming the most dangerous predator in any fight.' WHERE id = 26;
UPDATE sub_classes SET description = 'You carry the turning year inside you, calling down storms, frost, or summer heat at will. Your power shifts with the seasons, and the weather answers your mood.' WHERE id = 27;
UPDATE sub_classes SET description = 'You fight in a howling blur, swinging faster the angrier you get. Every blow that lands on you only feeds the next wave of steel.' WHERE id = 28;
UPDATE sub_classes SET description = 'You don''t dodge hits, you take them and keep walking. Your rage hardens your body until you stand like a mountain no one can move.' WHERE id = 29;
UPDATE sub_classes SET description = 'You smell blood and it drives you forward. Every wound you open makes you stronger, and the fight only ends when the field runs red.' WHERE id = 30;
UPDATE sub_classes SET description = 'You fight like a hunting cat, rushing in with sudden pounces and raking blows. You watch for weakness and strike the moment your prey falters.' WHERE id = 31;
UPDATE sub_classes SET description = 'You fight like a bear, grabbing hold and crushing the fight out of your foes. Your hide is thick, and once you have someone in your grip they are not getting out.' WHERE id = 32;
UPDATE sub_classes SET description = 'You have trained your body until it is as hard as iron. Your fists break guards, crack armor, and send shockwaves through anything you hit.' WHERE id = 33;
UPDATE sub_classes SET description = 'You fight shoulder to shoulder with your allies, spears leveled in an unbroken line. Together you hold ground that no single warrior could.' WHERE id = 34;
UPDATE sub_classes SET description = 'You leap high over the battlefield and drop on your enemies from above. Your foes learn to fear the sky, because that is where your spear comes from.' WHERE id = 35;
UPDATE sub_classes SET description = 'You wield a spear in each hand, striking and guarding in the same motion. Your paired points fill the air with steel, leaving foes nowhere safe to stand.' WHERE id = 36;
UPDATE sub_classes SET description = 'You carry the light of the dawn and pour it out on the battlefield. Your radiance shields your allies and burns away anything that hides from the sun.' WHERE id = 37;
UPDATE sub_classes SET description = 'You are a warden against things that should not walk the world. You seal away evil spirits and hollow horrors with sacred circles and holy sigils.' WHERE id = 38;
UPDATE sub_classes SET description = 'You serve a quieter faith, one of secrets spoken in the dark. Shadows carry your whispers, and every confession you hear becomes a debt you can collect.' WHERE id = 39;
UPDATE sub_classes SET description = 'You raise the dead to fight for you, from a single bone servant to a marching army. Death is not the end of your soldiers, only the start of their service.' WHERE id = 40;
UPDATE sub_classes SET description = 'You have dared to tame the hollow rot that devours magic and life. Your hungry pack spreads decay through your enemies and eats away at their spells.' WHERE id = 41;
UPDATE sub_classes SET description = 'You build your summons from scrap, gears, and stolen power. Your drones swarm the field and your iron machines march where flesh would fall.' WHERE id = 43;
UPDATE sub_classes SET description = 'You sing on the front line, and your songs turn fear into fury. Your battle hymns keep your allies marching when everything else says run.' WHERE id = 44;
UPDATE sub_classes SET description = 'You collect stories, languages, and secrets the way others collect coins. Your words cut as deep as any blade, and there is little you cannot learn to do.' WHERE id = 45;
UPDATE sub_classes SET description = 'You sing the songs of mourning, and your notes toll like a funeral bell. Your music shelters the living and calls the end for those whose time has come.' WHERE id = 46;
COMMIT;
